67	// Robustly parse the node id segments.
68	// Formats: "cmv_<id>", "ficha_<id>", "item_<id>", "nf_nota_<id>"
69	function parseNodeId(nodeId: string): { kind: string; kindId: number | null; isNotaNode: boolean } {
70	  if (nodeId.startsWith('nf_nota_')) {
71	    const raw = nodeId.slice('nf_nota_'.length);
72	    const id = parseInt(raw, 10);
73	    return { kind: 'nf', kindId: Number.isNaN(id) ? null : id, isNotaNode: true };
74	  }
75	  const underscoreIdx = nodeId.indexOf('_');
76	  if (underscoreIdx === -1) return { kind: nodeId, kindId: null, isNotaNode: false };
77	  const kind = nodeId.slice(0, underscoreIdx);
78	  const rawId = nodeId.slice(underscoreIdx + 1);
79	  const id = parseInt(rawId, 10);
80	  return { kind, kindId: Number.isNaN(id) ? null : id, isNotaNode: false };
81	}
