125	export const parseNodeId = (key: string): { type: CmvNodeKind; id: number } | null => {
126	  const idx = key.indexOf('_');
127	  if (idx < 0) return null;
128	  const typeStr = key.slice(0, idx);
129	  const id = Number(key.slice(idx + 1));
130	  if (!Number.isFinite(id)) return null;
131	  const validTypes: CmvNodeKind[] = ['cmv', 'ficha', 'insumo', 'nf', 'item'];
132	  if (validTypes.includes(typeStr as CmvNodeKind)) {
133	    return { type: typeStr as CmvNodeKind, id };
134	  }
135	  return null;
136	};
