150	  /** Itens de NF vinculados a insumos (retrocompat) */
151	  nfItems: RawCmvNFItem[];
152	  positions: Map<string, { x: number; y: number }>;
153	  savePosition: (key: string, x: number, y: number) => Promise<void>;
154	  refetch: () => Promise<void>;
