157	export function useCmvGraph(cmvId: number | null): CmvGraphData {
158	  const [loading, setLoading] = useState<boolean>(true);
159	  const [cmv, setCmv] = useState<RawCmv | null>(null);
160	  const [fichaData, setFichaData] = useState<RawCmvFicha | null>(null);
161	  const [items, setItems] = useState<RawCmvItem[]>([]);
162	  const [insumos, setInsumos] = useState<RawCmvInsumo[]>([]);
163	  const [embalagens, setEmbalagens] = useState<RawCmvEmbalagem[]>([]);
164	  const [nfEmbalagemItems, setNfEmbalagemItems] = useState<NfEmbalagemItem[]>([]);
165	  const [notas, setNotas] = useState<RawCmvNF[]>([]);
166	  const [nfItems, setNfItems] = useState<RawCmvNFItem[]>([]);
167	  const [positions, setPositions] = useState<Map<string, { x: number; y: number }>>(new Map());
168	
169	  const fetchAll = useCallback(async () => {
170	    if (cmvId === null) {
171	      setLoading(false);
172	      return;
173	    }
174	
175	    setLoading(true);
176	
177	    try {
178	      const [
179	        cmvRes,
180	        itensRes,
181	        insumosRes,
182	        posRes,
183	        nfRes,
184	        nfItensRes,
185	        embalagensRes,
186	        nfEmbalagemRes,
187	      ] = await Promise.all([
188	        supabase
189	          .from('cmv_fichas')
190	          .select('*, fichas_tecnicas(*)')
191	          .eq('id', cmvId)
192	          .maybeSingle(),
193	        supabase
194	          .from('cmv_itens')
195	          .select(
196	            '*, insumos(id,nome,preco_custo,unidade_compra,unidade_producao,categoria,fornecedor_principal), produtos_master(id,nome,preco_custo,unidade_medida), itens_nota_fiscal(id,nome_produto,valor_unitario,unidade,nota_id,notas_fiscais(fornecedor,numero_nota,data_nota))',
197	          )
198	          .eq('cmv_id', cmvId)
199	          .order('ordem'),
200	        supabase
201	          .from('insumos')
202	          .select('id,nome,preco_custo,unidade_compra,unidade_producao,categoria,fornecedor_principal')
203	          .eq('ativo', true)
204	          .order('nome'),
205	        supabase
206	          .from('cmv_canvas_positions')
207	          .select('*')
208	          .eq('cmv_id', cmvId),
209	        supabase
210	          .from('notas_fiscais')
211	          .select('id,fornecedor,numero_nota,valor_total,data_nota')
212	          .order('data_nota', { ascending: false })
213	          .limit(80),
214	        supabase
215	          .from('itens_nota_fiscal')
216	          .select('id,nota_id,insumo_id,nome_produto,valor_unitario,peso_unitario,unidade_base,unidade')
217	          .not('insumo_id', 'is', null)
218	          .limit(2000),
219	        // Catálogo de embalagens: produtos_master com setor = 'EMBALAGENS'
220	        supabase
221	          .from('produtos_master')
222	          .select('id,nome,preco_custo,unidade_medida,setor')
223	          .eq('ativo', true)
224	          .eq('setor', 'EMBALAGENS')
225	          .order('nome'),
226	        // Candidatos de NF para atrelar custo de embalagem
227	        supabase
228	          .from('itens_nota_fiscal')
229	          .select(
230	            'id,nota_id,nome_produto,valor_unitario,unidade,peso_unitario,notas_fiscais(fornecedor,numero_nota,data_nota)',
231	          )
232	          .eq('categoria', 'Embalagens')
233	          .gt('valor_unitario', 0)
234	          .limit(1000),
235	      ]);
236	
237	      // --- cmv_fichas + fichas_tecnicas ---
238	      if (cmvRes.data) {
239	        const raw = cmvRes.data as Record<string, unknown>;
240	        setCmv({
241	          id: raw.id as number,
242	          nome: raw.nome as string,
243	          ficha_tecnica_id: raw.ficha_tecnica_id as number,
244	          status: raw.status as string,
245	          custo_calculado: raw.custo_calculado as number | null,
246	          rendimento_quantidade: (raw.rendimento_quantidade as number | null) ?? null,
247	          rendimento_unidade: (raw.rendimento_unidade as string | null) ?? null,
248	          quantidade_ficha: (raw.quantidade_ficha as number | null) ?? null,
249	          unidade_ficha: (raw.unidade_ficha as string | null) ?? null,
250	        });
251	
252	        if (raw.fichas_tecnicas) {
253	          const ft = raw.fichas_tecnicas;
254	          const ficha = Array.isArray(ft) ? ft[0] : ft;
255	          if (ficha) {
256	            const f = ficha as Record<string, unknown>;
257	            setFichaData({
258	              id: f.id as number,
259	              nome: f.nome as string,
260	              custo_calculado: f.custo_calculado as number | null,
