262	              rendimento_unidade: f.rendimento_unidade as string,
263	              status: f.status as string,
264	            });
265	          }
266	        }
267	      } else {
268	        setCmv(null);
269	        setFichaData(null);
270	      }
271	
272	      // --- cmv_itens com joins novos ---
273	      if (itensRes.data) {
274	        const mappedItems = (itensRes.data as Record<string, unknown>[]).map((item) => {
275	          // insumo (legado)
276	          const insumosData = item.insumos;
277	          const insumoObj = insumosData
278	            ? Array.isArray(insumosData)
279	              ? insumosData[0]
280	              : insumosData
281	            : undefined;
282	
283	          // produto_master (embalagem escolhida)
284	          const pmData = item.produtos_master;
285	          const pmObj = pmData
286	            ? Array.isArray(pmData)
287	              ? pmData[0]
288	              : pmData
289	            : undefined;
290	          let produtoMaster: ResolvedProdutoMaster | undefined;
291	          if (pmObj) {
292	            const pm = pmObj as Record<string, unknown>;
293	            produtoMaster = {
294	              id: pm.id as number,
295	              nome: pm.nome as string,
296	              preco_custo: pm.preco_custo as number | null,
297	              unidade_medida: pm.unidade_medida as string | null,
298	            };
299	          }
300	
301	          // itens_nota_fiscal (NF travada) com notas_fiscais aninhado
302	          const nfItemData = item.itens_nota_fiscal;
303	          const nfItemObj = nfItemData
304	            ? Array.isArray(nfItemData)
305	              ? nfItemData[0]
306	              : nfItemData
307	            : undefined;
308	          let nfItem: ResolvedNfItem | undefined;
309	          if (nfItemObj) {
310	            const nfi = nfItemObj as Record<string, unknown>;
311	            const nfaNested = nfi.notas_fiscais;
312	            const nfa = nfaNested
313	              ? Array.isArray(nfaNested)
314	                ? (nfaNested[0] as Record<string, unknown>)
315	                : (nfaNested as Record<string, unknown>)
316	              : null;
317	            nfItem = {
318	              id: nfi.id as number,
319	              nome_produto: nfi.nome_produto as string | null,
320	              valor_unitario: nfi.valor_unitario as number | null,
321	              unidade: nfi.unidade as string | null,
322	              nota_id: nfi.nota_id as number,
323	              fornecedor: nfa ? (nfa.fornecedor as string | null) : null,
324	              numero_nota: nfa ? (nfa.numero_nota as string | null) : null,
325	              data_nota: nfa ? (nfa.data_nota as string | null) : null,
326	            };
327	          }
328	
329	          const mapped: RawCmvItem = {
330	            id: item.id as number,
331	            cmv_id: item.cmv_id as number,
332	            tipo: item.tipo as string,
333	            insumo_id: item.insumo_id as number | null,
334	            produto_master_id: (item.produto_master_id as number | null) ?? null,
335	            nf_item_id: (item.nf_item_id as number | null) ?? null,
336	            unidades_por_embalagem: (item.unidades_por_embalagem as number | null) ?? null,
337	            quantidade: item.quantidade as number,
338	            unidade: item.unidade as string,
339	            preco_unitario_esboco: item.preco_unitario_esboco as number | null,
340	            observacao: item.observacao as string | null,
341	            custo_calculado: item.custo_calculado as number | null,
342	            ordem: item.ordem as number,
343	            insumo: insumoObj as RawCmvInsumo | undefined,
344	            produtoMaster,
345	            nfItem,
346	          };
347	          return mapped;
348	        });
349	        setItems(mappedItems);
350	      } else {
351	        setItems([]);
352	      }
353	
354	      // --- insumos ativos (catálogo retrocompat) ---
355	      if (insumosRes.data) {
356	        setInsumos(insumosRes.data as unknown as RawCmvInsumo[]);
357	      }
358	
359	      // --- canvas positions ---
360	      if (posRes.data) {
361	        const newPositions = new Map<string, { x: number; y: number }>();
362	        for (const pos of posRes.data as Record<string, unknown>[]) {
363	          const key = `${pos.node_type}_${pos.node_id}`;
364	          newPositions.set(key, { x: pos.x as number, y: pos.y as number });
365	        }
366	        setPositions(newPositions);
367	      } else {
368	        setPositions(new Map());
369	      }
370	
371	      // --- notas fiscais (retrocompat) ---
372	      if (nfRes.data) {
373	        setNotas(nfRes.data as unknown as RawCmvNF[]);
374	      }
