403	                : (nfaNested as Record<string, unknown>)
404	              : null;
405	            const item: NfEmbalagemItem = {
406	              id: row.id as number,
407	              nota_id: row.nota_id as number,
408	              nome_produto: row.nome_produto as string | null,
409	              valor_unitario: row.valor_unitario as number | null,
