511	// Helper for unit conversions
512	const convertToBaseUnit = (value: number, unit: string): { value: number, type: 'mass' | 'volume' | 'count' | 'unknown' } => {
513	  const lowerUnit = unit.toLowerCase();
514	  if (lowerUnit === 'g') return { value: value, type: 'mass' };
515	  if (lowerUnit === 'kg') return { value: value * 1000, type: 'mass' }; // Convert to grams
516	  if (lowerUnit === 'ml') return { value: value, type: 'volume' };
517	  if (lowerUnit === 'l') return { value: value * 1000, type: 'volume' }; // Convert to milliliters
518	  if (lowerUnit === 'un') return { value: value, type: 'count' };
519	  return { value: value, type: 'unknown' };
520	};
521	
522	const convertFromBaseUnit = (baseValue: number, baseType: 'mass' | 'volume' | 'count' | 'unknown', targetUnit: string): number => {
523	  const lowerTargetUnit = targetUnit.toLowerCase();
524	  if (baseType === 'mass') {
525	    if (lowerTargetUnit === 'g') return baseValue;
526	    if (lowerTargetUnit === 'kg') return baseValue / 1000;
527	  } else if (baseType === 'volume') {
528	    if (lowerTargetUnit === 'ml') return baseValue;
529	    if (lowerTargetUnit === 'l') return baseValue / 1000;
530	  } else if (baseType === 'count') {
531	    if (lowerTargetUnit === 'un') return baseValue;
532	  }
533	  return baseValue; // Fallback if target unit is incompatible or unknown
534	};
535	
536	const getConvertedValue = (value: number, fromUnit: string, toUnit: string): number => {
537	  if (fromUnit.toLowerCase() === toUnit.toLowerCase()) return value;
538	
539	  const { value: baseValue, type: baseType } = convertToBaseUnit(value, fromUnit);
540	  return convertFromBaseUnit(baseValue, baseType, toUnit);
