import { memo, useCallback, useEffect, useState, useMemo } from 'react';
import {
  ReactFlow,
  ReactFlowProvider,
  Background,
  BackgroundVariant,
  MiniMap,
  Panel,
  useNodesState,
  useEdgesState,
  useReactFlow,
  Handle,
  Position,
  type Node,
  type Edge,
  type NodeTypes,
  type NodeDragHandler,
  type NodeMouseHandler,
} from '@xyflow/react';
import '@xyflow/react/dist/style.css';
import { useNavigate, useSearchParams } from 'react-router-dom';
import { supabase } from '@/integrations/supabase/client';
import { useCmvGraph } from '@/features/financeiro/model/useCmvGraph';
import { layoutGraph } from '@/components/producao/configurador/layout';
import { toast } from 'sonner';
import {
  ArrowLeft,
  Calculator,
  ChefHat,
  Package,
  DollarSign,
  Receipt,
  Loader2,
} from 'lucide-react';
import { Button } from '@/shared/ui/button';
import { CmvNodePalette } from './cmv/CmvNodePalette';
import { CmvDetailPanel } from './cmv/CmvDetailPanel';
import { CmvBottomToolbar } from './cmv/CmvBottomToolbar';

// ---------------------------------------------------------------------------
// HELPERS
// ---------------------------------------------------------------------------

const fmt = (v: number | null | undefined): string => {
  if (v === null || v === undefined) return 'R$ 0,00';
  return v.toLocaleString('pt-BR', { style: 'currency', currency: 'BRL' });
};

const STATUS_COLORS: Record<string, string> = {
  rascunho: 'bg-zinc-200/80 text-zinc-700 dark:bg-zinc-700 dark:text-zinc-300',
  aprovada: 'bg-emerald-100 text-emerald-700 dark:bg-emerald-800/60 dark:text-emerald-300',
  obsoleta: 'bg-zinc-200/80 text-zinc-500 dark:bg-zinc-800 dark:text-zinc-500',
};

// ---------------------------------------------------------------------------
// NODE DATA TYPES
// ---------------------------------------------------------------------------

interface CmvRootNodeData extends Record<string, unknown> {
  nome: string;
  custo: number | null;
  status: string;
  kind: string;
  rendimentoQty: number | null;
  rendimentoUnit: string | null;
}

interface FichaBaseNodeData extends Record<string, unknown> {
  nome: string;
  custoUnitario: number;
  rendimento: string;
  custoTotal: number | null;
  rendQty: number;
  rendimento_unidade: string;
  kind: string;
  quantidadeFicha: number | null;
  unidadeFicha: string | null;
}

interface CmvItemNodeData extends Record<string, unknown> {
  tipo: string;
  quantidade: number;
  unidade: string;
  custo: number | null;
  label: string;
  kind: string;
  _rawItemId: number;
}

interface NFNodeData extends Record<string, unknown> {
  fornecedor: string;
  numero: string | null;
  valor: number | null;
  kind: string;
}

// ---------------------------------------------------------------------------
// NODE COMPONENTS
// ---------------------------------------------------------------------------

// @ts-expect-error ReactFlow NodeProps generic mismatch with our typed data shape
const CmvRootNode = memo(function CmvRootNode({ data }: { data: CmvRootNodeData }) {
  return (
    <div className="relative px-5 py-4 rounded-2xl border border-[#57715B]/50 bg-[#57715B]/90 backdrop-blur-md text-white min-w-[260px] shadow-2xl shadow-[#57715B]/40">
      <div className="flex items-start justify-between mb-2 gap-2">
        <div className="flex items-center gap-1.5 opacity-80">
          <Calculator size={12} />
          <span className="text-[9px] font-bold uppercase tracking-wider">Produto Final</span>
        </div>
        <span
          className={`text-[9px] px-2 py-0.5 rounded-full font-bold uppercase tracking-wide ${STATUS_COLORS[data.status] ?? STATUS_COLORS.rascunho}`}
        >
          {data.status}
        </span>
      </div>
      <h3 className="text-base font-bold truncate leading-tight mb-2">{data.nome}</h3>
      {data.rendimentoQty != null && data.rendimentoUnit && (
        <p className="text-[10px] text-white/70 mb-1.5">
          Rende: {data.rendimentoQty} {data.rendimentoUnit}
        </p>
      )}
      <p className="text-2xl font-black tabular-nums">{fmt(data.custo)}</p>
      <Handle
        type="target"
        position={Position.Left}
        className="!w-3.5 !h-3.5 !bg-white/60 !border-2 !border-white/30"
      />
    </div>
  );
});

// @ts-expect-error ReactFlow NodeProps generic mismatch with our typed data shape
const FichaBaseNode = memo(function FichaBaseNode({ data }: { data: FichaBaseNodeData }) {
  const custoUnit = data.rendQty > 0 ? (data.custoTotal ?? 0) / data.rendQty : 0;
  return (
    <div className="relative px-5 py-4 rounded-2xl border border-amber-500/40 bg-amber-700/80 backdrop-blur-md text-white min-w-[240px] shadow-xl shadow-amber-700/30">
      <div className="flex items-center gap-1.5 opacity-80 mb-2">
        <ChefHat size={12} />
        <span className="text-[9px] font-bold uppercase tracking-wider">Ficha Técnica Base</span>
      </div>
      <h3 className="text-base font-semibold truncate mb-1">{data.nome}</h3>
      <div className="flex items-end justify-between mt-2">
        <div>
          <p className="text-[9px] opacity-60 leading-none mb-0.5">Custo total</p>
          <p className="text-xl font-bold tabular-nums">{fmt(data.custoTotal)}</p>
          {data.rendQty > 0 && (
            <p className="text-[10px] text-amber-200 mt-1">
              {fmt(custoUnit)} / {data.rendimento_unidade}
            </p>
          )}
        </div>
        <div className="text-right">
          <span className="text-[10px] px-2 py-0.5 bg-white/20 rounded-full block mb-1">
            {data.rendimento}
          </span>
          {data.quantidadeFicha != null && data.unidadeFicha && (
            <span className="text-[10px] text-amber-200 block">
              usa {data.quantidadeFicha}{data.unidadeFicha} no produto
            </span>
          )}
        </div>
      </div>
      <Handle
        type="source"
        position={Position.Right}
        className="!w-3 !h-3 !bg-amber-300 !border-2 !border-white"
      />
    </div>
  );
});

// @ts-expect-error ReactFlow NodeProps generic mismatch with our typed data shape
const CmvItemNode = memo(function CmvItemNode({
  data,
  selected,
}: {
  data: CmvItemNodeData;
  selected: boolean;
}) {
  const isEmb = data.tipo === 'embalagem';
  const color = isEmb
    ? 'bg-blue-600/80 border-blue-400/40'
    : 'bg-orange-700/60 border-dashed border-orange-400/60';
  const icon = isEmb ? <Package size={12} /> : <DollarSign size={12} />;
  const label = isEmb ? 'Embalagem' : 'Custo avulso';

  return (
    <div
      className={`relative px-4 py-3 rounded-xl border backdrop-blur-md text-zinc-100 min-w-[200px] shadow-lg transition-all duration-150 ${color} ${selected ? 'ring-2 ring-white/40 scale-[1.02]' : 'hover:shadow-xl hover:-translate-y-0.5'}`}
    >
      <div className="flex items-center gap-1.5 mb-2">
        <span className="opacity-80">{icon}</span>
        <span className="text-[9px] font-bold uppercase tracking-wider opacity-80">{label}</span>
      </div>
      <h4 className="text-sm font-semibold truncate mb-1.5">{data.label}</h4>
      <div className="flex items-end justify-between">
        <span className="text-[11px] text-white/70">
          {data.quantidade} {data.unidade}
        </span>
        <span className="text-base font-bold tabular-nums">{fmt(data.custo)}</span>
      </div>
      <Handle
        type="target"
        position={Position.Left}
        className="!w-2.5 !h-2.5 !bg-white/40 !border-2 !border-white/20"
      />
      <Handle
        type="source"
        position={Position.Right}
        className="!w-2.5 !h-2.5 !bg-white/60 !border-2 !border-white/30"
      />
    </div>
  );
});

// @ts-expect-error ReactFlow NodeProps generic mismatch with our typed data shape
const NFNode = memo(function NFNode({ data }: { data: NFNodeData }) {
  return (
    <div className="px-3 py-2 rounded-lg border border-cyan-400/30 bg-cyan-700/70 backdrop-blur-sm text-white min-w-[160px] shadow-md">
      <div className="flex items-center gap-1 mb-1 opacity-70">
        <Receipt size={10} />
        <span className="text-[9px] font-bold uppercase">Nota Fiscal</span>
      </div>
      <h4 className="text-[11px] font-semibold truncate">{data.fornecedor ?? 'Fornecedor'}</h4>
      {data.numero && <p className="text-[9px] opacity-60">#{data.numero}</p>}
      <Handle
        type="source"
        position={Position.Right}
        className="!w-2 !h-2 !bg-cyan-300 !border-2 !border-white"
      />
    </div>
  );
});

const nodeTypes: NodeTypes = {
  cmv: CmvRootNode,
  ficha: FichaBaseNode,
  cmvItem: CmvItemNode,
  nf: NFNode,
};

// ---------------------------------------------------------------------------
// INNER COMPONENT
// ---------------------------------------------------------------------------

function CmvConfiguratorInner() {
  const navigate = useNavigate();
  const [searchParams] = useSearchParams();
  const cmvIdParam = searchParams.get('focus');
  const cmvId = cmvIdParam ? parseInt(cmvIdParam, 10) : null;

  const {
    loading,
    cmv,
    fichaData,
    items,
    embalagens,
    nfEmbalagemItems,
    positions,
    savePosition,
    refetch,
  } = useCmvGraph(cmvId);

  const { fitView } = useReactFlow();
  const [nodes, setNodes, onNodesChange] = useNodesState([]);
  const [edges, setEdges, onEdgesChange] = useEdgesState([]);
  const [selectedNodeId, setSelectedNodeId] = useState<string | null>(null);

  const handleNodeClick: NodeMouseHandler = useCallback((_evt, node) => {
    setSelectedNodeId(node.id);
  }, []);

  const handlePaneClick = useCallback(() => {
    setSelectedNodeId(null);
  }, []);

  const { custoReceita, custoEmbalagens, custoAvulsos, custoTotal } = useMemo(() => {
    const embalagensTotal = items
      .filter((i) => i.tipo === 'embalagem')
      .reduce((s, i) => s + (i.custo_calculado ?? 0), 0);
    const avulsosTotal = items
      .filter((i) => i.tipo === 'outro')
      .reduce((s, i) => s + (i.custo_calculado ?? 0), 0);
    const total = cmv?.custo_calculado ?? 0;
    // Receita = total - embalagens - avulsos (conforme calculado pelo banco)
    const receitaContrib = total - embalagensTotal - avulsosTotal;
    return {
      custoReceita: receitaContrib,
      custoEmbalagens: embalagensTotal,
      custoAvulsos: avulsosTotal,
      custoTotal: total,
    };
  }, [items, cmv]);

  const buildGraph = useCallback(() => {
    if (!cmv) return;

    const newNodes: Node[] = [];
    const newEdges: Edge[] = [];
    const rootId = `cmv_${cmv.id}`;

    newNodes.push({
      id: rootId,
      type: 'cmv',
      data: {
        nome: cmv.nome,
        custo: cmv.custo_calculado,
        status: cmv.status,
        kind: 'cmv',
        rendimentoQty: cmv.rendimento_quantidade,
        rendimentoUnit: cmv.rendimento_unidade,
      } as CmvRootNodeData,
      position: positions.get(rootId) ?? { x: 800, y: 300 },
    });

    if (fichaData) {
      const fId = `ficha_${fichaData.id}`;
      const rendQty = fichaData.rendimento_quantidade || 1;
      const custoUnitario = (fichaData.custo_calculado ?? 0) / rendQty;

      newNodes.push({
        id: fId,
        type: 'ficha',
        data: {
          nome: fichaData.nome,
          custoUnitario,
          rendimento: `${fichaData.rendimento_quantidade} ${fichaData.rendimento_unidade}`,
          custoTotal: fichaData.custo_calculado,
          rendQty,
          rendimento_unidade: fichaData.rendimento_unidade,
          kind: 'ficha',
          quantidadeFicha: cmv.quantidade_ficha,
          unidadeFicha: cmv.unidade_ficha,
        } as FichaBaseNodeData,
        position: positions.get(fId) ?? { x: 400, y: 300 },
      });

      newEdges.push({
        id: `e-${fId}-${rootId}`,
        source: fId,
        target: rootId,
        animated: true,
        style: { stroke: '#F59E0B', strokeWidth: 3 },
      });
    }

    items.forEach((item, idx) => {
      const itemId = `item_${item.id}`;
      const label =
        item.produtoMaster?.nome ?? item.insumo?.nome ?? item.observacao ?? 'Embalagem';

      newNodes.push({
        id: itemId,
        type: 'cmvItem',
        data: {
          tipo: item.tipo,
          quantidade: item.quantidade,
          unidade: item.unidade,
          custo: item.custo_calculado,
          label,
          kind: 'cmvItem',
          _rawItemId: item.id,
        } as CmvItemNodeData,
        position: positions.get(itemId) ?? { x: 400, y: 100 + idx * 160 },
      });

      newEdges.push({
        id: `e-${itemId}-${rootId}`,
        source: itemId,
        target: rootId,
        style: { stroke: '#52525b', strokeWidth: 2 },
      });
    });

    const addedNotaIds = new Set<number>();
    items.forEach((item) => {
      if (item.nf_item_id && item.nfItem?.nota_id) {
        const notaId = item.nfItem.nota_id;
        if (!addedNotaIds.has(notaId)) {
          addedNotaIds.add(notaId);
          const nfId = `nf_nota_${notaId}`;
          newNodes.push({
            id: nfId,
            type: 'nf',
            data: {
              fornecedor: item.nfItem.fornecedor ?? 'Fornecedor',
              numero: item.nfItem.numero_nota,
              valor: null,
              kind: 'nf',
            } as NFNodeData,
            position: positions.get(nfId) ?? { x: 50, y: 50 + addedNotaIds.size * 140 },
          });
        }

        const nfId = `nf_nota_${notaId}`;
        const itemId = `item_${item.id}`;
        newEdges.push({
          id: `e-${nfId}-${itemId}`,
          source: nfId,
          target: itemId,
          style: { stroke: '#22d3ee', strokeWidth: 1.5, strokeDasharray: '4 2' },
        });
      }
    });

    const hasAllPositions = newNodes.every((n) => positions.has(n.id));
    if (!hasAllPositions && newNodes.length > 0) {
      const laid = layoutGraph(newNodes, newEdges, 'LR');
      setNodes(laid);
    } else {
      setNodes(newNodes);
    }
    setEdges(newEdges);

    requestAnimationFrame(() => {
      fitView({ padding: 0.12, duration: 400 });
    });
  }, [cmv, fichaData, items, positions, fitView, setNodes, setEdges]);

  useEffect(() => {
    if (!loading) buildGraph();
  }, [loading, buildGraph]);

  const handleNodeDragStop: NodeDragHandler = useCallback(
    (_evt, node) => {
      if (!node.id.startsWith('nf_nota_')) {
        savePosition(node.id, node.position.x, node.position.y);
      }
    },
    [savePosition],
  );

  const handleAddEmbalagem = useCallback(
    async (embId: number) => {
      if (!cmvId) return;
      const { error } = await supabase.from('cmv_itens').insert({
        cmv_id: cmvId,
        tipo: 'embalagem',
        produto_master_id: embId,
        quantidade: 1,
        unidade: 'un',
        ordem: items.length,
      } as Record<string, unknown>);
      if (error) {
        toast.error(error.message);
        return;
      }
      toast.success('Embalagem adicionada');
      await refetch();
    },
    [cmvId, items.length, refetch],
  );

  const handleAddAvulso = useCallback(
    async (nome: string, valor: number) => {
      if (!cmvId) return;
      const { error } = await supabase.from('cmv_itens').insert({
        cmv_id: cmvId,
        tipo: 'outro',
        observacao: nome,
        preco_unitario_esboco: valor,
        quantidade: 1,
        unidade: 'un',
        ordem: items.length,
      } as Record<string, unknown>);
      if (error) {
        toast.error(error.message);
        return;
      }
      toast.success('Custo avulso adicionado');
      await refetch();
    },
    [cmvId, items.length, refetch],
  );

  if (loading || !cmv) {
    return (
      <div className="h-[100dvh] w-full flex items-center justify-center text-slate-500 dark:text-slate-400">
        <Loader2 className="animate-spin" />
      </div>
    );
  }

  return (
    <div className="fixed inset-0 bg-zinc-50 dark:bg-zinc-950 font-sans">
      {/* Ambient glows */}
      <div className="fixed top-[-10%] left-[-10%] w-[500px] h-[500px] bg-[#57715B]/5 blur-[80px] rounded-full pointer-events-none" />
      <div className="fixed top-[20%] right-[-5%] w-[400px] h-[400px] bg-[#C5A065]/5 blur-[80px] rounded-full pointer-events-none" />

      <ReactFlow
        nodes={nodes}
        edges={edges}
        nodeTypes={nodeTypes}
        onNodesChange={onNodesChange}
        onEdgesChange={onEdgesChange}
        onNodeDragStop={handleNodeDragStop}
        onNodeClick={handleNodeClick}
        onPaneClick={handlePaneClick}
        minZoom={0.2}
        maxZoom={3}
      >
        <Background variant={BackgroundVariant.Dots} color="#57715B" gap={24} className="opacity-20" />
        <MiniMap
          zoomable
          pannable
          nodeClassName={(n) => {
            if (n.type === 'cmv') return '!fill-[#57715B]';
            if (n.type === 'ficha') return '!fill-amber-500';
            if (n.type === 'cmvItem') {
              const d = n.data as CmvItemNodeData;
              return d.tipo === 'embalagem' ? '!fill-blue-500' : '!fill-orange-500';
            }
            if (n.type === 'nf') return '!fill-cyan-500';
            return '!fill-slate-500';
          }}
        />

        {/* Back arrow + CMV name header */}
        <Panel position="top-left">
          <div className="flex items-center gap-2 bg-white/90 dark:bg-slate-900/85 border border-[#57715B]/10 backdrop-blur-md rounded-xl px-3 py-2 shadow-xl">
            <Button
              variant="ghost"
              size="icon"
              className="h-9 w-9"
              onClick={() => navigate('/financeiro/cmv')}
            >
              <ArrowLeft size={16} />
            </Button>
            <div className="w-px h-5 bg-[#57715B]/15" />
            <div className="flex items-center gap-2">
              <Calculator size={14} className="text-[#57715B]" />
              <span className="text-sm font-semibold truncate max-w-[180px]">{cmv.nome}</span>
              <span
                className={`text-[10px] px-2 py-0.5 rounded-full font-bold uppercase tracking-wide ${STATUS_COLORS[cmv.status] ?? STATUS_COLORS.rascunho}`}
              >
                {cmv.status}
              </span>
            </div>
          </div>
        </Panel>

        {/* Legend */}
        <Panel position="top-right">
          <div className="flex flex-col gap-1.5 bg-white/90 dark:bg-slate-900/85 border border-[#57715B]/10 backdrop-blur-md rounded-xl p-3 shadow-lg text-[10px] text-slate-500 dark:text-slate-400">
            <p className="text-[9px] font-bold uppercase tracking-widest mb-1 text-[#57715B]">
              Legenda
            </p>
            <div className="flex items-center gap-1.5">
              <Calculator size={10} className="text-[#57715B]" />
              <span>Produto Final</span>
            </div>
            <div className="flex items-center gap-1.5">
              <ChefHat size={10} className="text-amber-500" />
              <span>Ficha Técnica</span>
            </div>
            <div className="flex items-center gap-1.5">
              <Package size={10} className="text-blue-400" />
              <span>Embalagem</span>
            </div>
            <div className="flex items-center gap-1.5">
              <DollarSign size={10} className="text-orange-400" />
              <span>Custo avulso</span>
            </div>
            <div className="flex items-center gap-1.5">
              <Receipt size={10} className="text-cyan-400" />
              <span>Nota Fiscal</span>
            </div>
          </div>
        </Panel>

        {/* Cost summary panel */}
        <Panel position="bottom-left">
          <div className="bg-white/90 dark:bg-slate-900/85 border border-[#57715B]/10 backdrop-blur-md rounded-xl p-4 shadow-2xl flex flex-col gap-2 min-w-[240px] max-w-[300px]">
            {/* Rendimento final do produto */}
            {cmv.rendimento_quantidade != null && cmv.rendimento_unidade && (
              <div className="flex items-center justify-between text-xs pb-2 border-b border-[#57715B]/10">
                <span className="text-muted-foreground font-semibold uppercase tracking-wider text-[9px]">
                  Produto Final
                </span>
                <span className="font-bold text-[#57715B]">
                  {cmv.rendimento_quantidade} {cmv.rendimento_unidade}
                </span>
              </div>
            )}
            {/* Linha da receita */}
            <div className="flex items-center justify-between text-xs">
              <span className="text-muted-foreground flex items-center gap-1.5 min-w-0">
                <ChefHat size={12} className="shrink-0" />
                <span className="truncate">
                  {fichaData
                    ? cmv.quantidade_ficha != null && cmv.unidade_ficha
                      ? `Receita (${cmv.quantidade_ficha}${cmv.unidade_ficha} de ${fichaData.nome})`
                      : `Receita (${fichaData.nome})`
                    : 'Receita'}
                </span>
              </span>
              <span className="font-semibold ml-2 shrink-0">{fmt(custoReceita)}</span>
            </div>
            <div className="flex items-center justify-between text-xs">
              <span className="text-muted-foreground flex items-center gap-1.5">
                <Package size={12} /> Embalagens
              </span>
              <span className="font-semibold">{fmt(custoEmbalagens)}</span>
            </div>
            <div className="flex items-center justify-between text-xs pb-2 border-b border-[#57715B]/10">
              <span className="text-muted-foreground flex items-center gap-1.5">
                <DollarSign size={12} /> Avulsos
              </span>
              <span className="font-semibold">{fmt(custoAvulsos)}</span>
            </div>
            <div className="flex items-center justify-between">
              <span className="text-xs font-bold uppercase tracking-wider text-[#57715B]">
                Custo Final
              </span>
              <span className="text-lg font-black text-[#57715B] tabular-nums">
                {fmt(custoTotal)}
              </span>
            </div>
            {cmv.rendimento_quantidade != null && cmv.rendimento_quantidade > 0 && (
              <div className="text-[10px] text-muted-foreground text-right">
                = {fmt(custoTotal / cmv.rendimento_quantidade)} / {cmv.rendimento_unidade ?? 'un'}
              </div>
            )}
          </div>
        </Panel>
      </ReactFlow>

      <CmvNodePalette
        embalagens={embalagens}
        onAddEmbalagem={handleAddEmbalagem}
        onAddAvulso={handleAddAvulso}
      />

      <CmvDetailPanel
        selectedNodeId={selectedNodeId}
        cmv={cmv}
        fichaData={fichaData}
        items={items}
        custoReceita={custoReceita}
        custoEmbalagens={custoEmbalagens}
        custoAvulsos={custoAvulsos}
        custoTotal={custoTotal}
        nfEmbalagemItems={nfEmbalagemItems}
        onClose={() => setSelectedNodeId(null)}
        onRefetch={refetch}
      />

      <CmvBottomToolbar onSavePosition={savePosition} />
    </div>
  );
}

