export function CmvDetailPanel({
  selectedNodeId,
  cmv,
  fichaData,
  items,
  custoReceita,
  custoEmbalagens,
  custoAvulsos,
  custoTotal,
  nfEmbalagemItems,
  onClose,
  onRefetch,
}: CmvDetailPanelProps) {
  // --- Shared state ---
  const [atrelarNFOpen, setAtrelarNFOpen] = useState(false);
  const [deleteDialogOpen, setDeleteDialogOpen] = useState(false);
  const [isSaving, setIsSaving] = useState(false);
  const [isDeleting, setIsDeleting] = useState(false);

  // --- Item (embalagem/avulso) fields ---
  const [editQty, setEditQty] = useState('');
  const [editUnit, setEditUnit] = useState('');
  const [editPreco, setEditPreco] = useState('');
  const [editObs, setEditObs] = useState('');
  const [editUnidadesPorEmbalagem, setEditUnidadesPorEmbalagem] = useState('');

  // --- Ficha node edit fields (quantidade_ficha + unidade_ficha on cmv_fichas) ---
  const [editQuantidadeFicha, setEditQuantidadeFicha] = useState('');
  const [editUnidadeFicha, setEditUnidadeFicha] = useState<string>('g');
  const [isSavingFicha, setIsSavingFicha] = useState(false);

  // --- CMV node edit fields (nome + rendimento on cmv_fichas) ---
  const [editNomeProduto, setEditNomeProduto] = useState('');
  const [editRendQty, setEditRendQty] = useState('');
  const [editRendUnit, setEditRendUnit] = useState('');
  const [isSavingCmv, setIsSavingCmv] = useState(false);

  // ---------------------------------------------------------------------------
  // Formatters
  // ---------------------------------------------------------------------------

  const formatMoney = (v: number | null | undefined) => {
    if (v == null) return 'R$ 0,00';
    return v.toLocaleString('pt-BR', { style: 'currency', currency: 'BRL' });
  };

  const formatDate = (d: string | null) => {
    if (!d) return '';
    return new Date(d).toLocaleDateString('pt-BR');
  };

  // ---------------------------------------------------------------------------
  // Derived state
  // ---------------------------------------------------------------------------

  const { kind, kindId, isNotaNode } = useMemo(
    () =>
      selectedNodeId
        ? parseNodeId(selectedNodeId)
        : { kind: '', kindId: null, isNotaNode: false },
    [selectedNodeId],
  );

  const selectedItem = useMemo(() => {
    if (kind === 'item' && kindId !== null) return items.find((i) => i.id === kindId);
    return null;
  }, [kind, kindId, items]);

  const selectedNFItem = useMemo(() => {
    if (selectedItem?.nf_item_id) {
      return nfEmbalagemItems.find((n) => n.id === selectedItem.nf_item_id);
    }
    return null;
  }, [selectedItem, nfEmbalagemItems]);

  const selectedNotaNodesData = useMemo(() => {
    if (isNotaNode && kindId !== null) {
      return nfEmbalagemItems.find((n) => n.nota_id === kindId);
    }
    return null;
  }, [isNotaNode, kindId, nfEmbalagemItems]);

  // Custo unitário da ficha base (R$/rendimento_unidade)
  const fichaUnitCost = useMemo(() => {
    if (!fichaData || fichaData.rendimento_quantidade <= 0) return 0;
    return (fichaData.custo_calculado ?? 0) / fichaData.rendimento_quantidade;
  }, [fichaData]);

  // Preview em tempo real da contribuição estimada (antes de salvar)
  const fichaContribPreview = useMemo(() => {
    if (!fichaData) return null;
    const qty = parseFloat(editQuantidadeFicha);
    if (Number.isNaN(qty) || qty <= 0) return null;
    const convertedQty = convertUnits(qty, editUnidadeFicha, fichaData.rendimento_unidade);
    return fichaUnitCost * convertedQty;
  }, [editQuantidadeFicha, editUnidadeFicha, fichaUnitCost, fichaData]);

  // ---------------------------------------------------------------------------
  // Sync fields when selection changes
  // ---------------------------------------------------------------------------

  useEffect(() => {
    if (selectedItem) {
      setEditQty(selectedItem.quantidade?.toString() ?? '');
      setEditUnit(selectedItem.unidade ?? '');
      setEditPreco(selectedItem.preco_unitario_esboco?.toString() ?? '');
      setEditObs(selectedItem.observacao ?? '');
      setEditUnidadesPorEmbalagem(selectedItem.unidades_por_embalagem?.toString() ?? '');
    }
  }, [selectedItem]);

  useEffect(() => {
    if (kind === 'ficha' && cmv) {
      setEditQuantidadeFicha(cmv.quantidade_ficha?.toString() ?? '');
      setEditUnidadeFicha(cmv.unidade_ficha ?? 'g');
    }
  }, [kind, cmv]);

  useEffect(() => {
    if (kind === 'cmv' && cmv) {
      setEditNomeProduto(cmv.nome ?? '');
      setEditRendQty(cmv.rendimento_quantidade?.toString() ?? '');
      setEditRendUnit(cmv.rendimento_unidade ?? 'un');
    }
  }, [kind, cmv]);

  // ---------------------------------------------------------------------------
  // Handlers — items
  // ---------------------------------------------------------------------------

  const handleSaveItem = async () => {
    if (!selectedItem) return;
    setIsSaving(true);

    const updates: Record<string, unknown> = {
      quantidade: parseFloat(editQty) || 0,
      unidade: editUnit,
      observacao: editObs,
      unidades_por_embalagem: parseFloat(editUnidadesPorEmbalagem) || 1,
    };

    if (
      selectedItem.tipo === 'outro' ||
      (selectedItem.tipo === 'embalagem' && !selectedItem.nf_item_id)
    ) {
      updates.preco_unitario_esboco = parseFloat(editPreco) || 0;
    }

    const { error } = await supabase.from('cmv_itens').update(updates).eq('id', selectedItem.id);
    setIsSaving(false);

    if (error) {
      toast.error('Erro ao salvar: ' + error.message);
    } else {
      toast.success('Item atualizado');
      onRefetch();
    }
  };

  const handleDeleteItem = async () => {
    if (!selectedItem) return;
    setIsDeleting(true);
    const { error } = await supabase.from('cmv_itens').delete().eq('id', selectedItem.id);
    setIsDeleting(false);
    setDeleteDialogOpen(false);

    if (error) {
      toast.error('Erro ao excluir: ' + error.message);
    } else {
      toast.success('Item excluído');
      onClose();
      onRefetch();
    }
  };

  const handleDesatrelarNF = async () => {
    if (!selectedItem) return;
    setIsSaving(true);
    const { error } = await supabase
      .from('cmv_itens')
      .update({ nf_item_id: null } as Record<string, unknown>)
      .eq('id', selectedItem.id);
    setIsSaving(false);
    if (error) {
      toast.error('Erro ao desatrelar: ' + error.message);
    } else {
      toast.success('NF desatrelada');
      onRefetch();
    }
  };

  // ---------------------------------------------------------------------------
  // Handlers — ficha node
  // ---------------------------------------------------------------------------

  const handleSaveFicha = async () => {
    if (!cmv) return;
    setIsSavingFicha(true);
    const { error } = await supabase
      .from('cmv_fichas')
      .update({
        quantidade_ficha: parseFloat(editQuantidadeFicha) || null,
        unidade_ficha: editUnidadeFicha || null,
      } as Record<string, unknown>)
      .eq('id', cmv.id);
    setIsSavingFicha(false);
    if (error) {
      toast.error('Erro ao salvar: ' + error.message);
    } else {
      toast.success('Quantidade da receita atualizada');
      onRefetch();
    }
  };

  // ---------------------------------------------------------------------------
  // Handlers — CMV root node
  // ---------------------------------------------------------------------------

  const handleSaveCmv = async () => {
    if (!cmv) return;
    setIsSavingCmv(true);
    const { error } = await supabase
      .from('cmv_fichas')
      .update({
        nome: editNomeProduto || cmv.nome,
        rendimento_quantidade: parseFloat(editRendQty) || null,
        rendimento_unidade: editRendUnit || null,
      } as Record<string, unknown>)
      .eq('id', cmv.id);
    setIsSavingCmv(false);
    if (error) {
      toast.error('Erro ao salvar: ' + error.message);
    } else {
      toast.success('Produto final atualizado');
      onRefetch();
    }
  };

  // ---------------------------------------------------------------------------
  // Guard
  // ---------------------------------------------------------------------------

  if (!selectedNodeId) return null;

  // ---------------------------------------------------------------------------
  // Render
  // ---------------------------------------------------------------------------

  return (
    <>
      <aside className="absolute top-14 right-0 bottom-0 w-full sm:w-[420px] z-20 bg-white/95 dark:bg-[#1A1A1A]/95 backdrop-blur-xl border-l border-[#57715B]/10 shadow-2xl overflow-y-auto overflow-x-hidden animate-in slide-in-from-right duration-300 flex flex-col">
        {/* ── HEADER ── */}
        <header className="sticky top-0 bg-white/95 dark:bg-[#1A1A1A]/95 border-b border-[#57715B]/10 p-4 flex items-center justify-between z-10 shrink-0">
          <div className="flex items-center gap-2">
            {kind === 'cmv' && <Calculator className="text-[#57715B]" size={20} />}
            {kind === 'ficha' && <ChefHat className="text-amber-500" size={20} />}
            {kind === 'item' && selectedItem?.tipo === 'embalagem' && (
              <Package className="text-blue-500" size={20} />
            )}
            {kind === 'item' && selectedItem?.tipo === 'outro' && (
              <DollarSign className="text-orange-500" size={20} />
            )}
            {isNotaNode && <Receipt className="text-cyan-500" size={20} />}
            <span className="font-semibold text-sm">
              {kind === 'cmv' && 'Produto Final'}
              {kind === 'ficha' && 'Ficha Base'}
              {kind === 'item' && selectedItem?.tipo === 'embalagem' && 'Detalhes da Embalagem'}
              {kind === 'item' && selectedItem?.tipo === 'outro' && 'Detalhes do Custo Avulso'}
              {isNotaNode && 'Detalhes da Nota Fiscal'}
            </span>
          </div>
          <Button
            variant="ghost"
            size="icon"
            aria-label="Fechar painel"
            className="h-10 w-10 hover:bg-[#57715B]/10 active:bg-[#57715B]/10"
            onClick={onClose}
          >
            <X size={18} className="text-muted-foreground" />
          </Button>
        </header>

        <div className="p-5 flex-1 overflow-y-auto space-y-6">

          {/* ══════════════════════════════════════════
              NODE CMV — Produto Final
          ══════════════════════════════════════════ */}
          {kind === 'cmv' && cmv && (
            <div className="space-y-5">
              {/* Editor de identidade do produto final */}
              <div>
                <p className="text-[10px] uppercase tracking-widest text-muted-foreground mb-3 font-semibold">
                  Identidade do Produto Final
                </p>
                <div className="space-y-3">
                  <div className="space-y-1">
                    <Label className="text-xs">Nome do Produto Final</Label>
                    <Input
                      value={editNomeProduto}
                      onChange={(e) => setEditNomeProduto(e.target.value)}
                      placeholder="Ex.: Canjica 200ml no pote"
                      className="bg-white/60 dark:bg-black/20 border-[#57715B]/15 focus-visible:ring-[#57715B]/30 rounded-xl"
                    />
                  </div>
                  <div className="flex gap-2">
                    <div className="flex-1 space-y-1">
                      <Label className="text-xs">Rendimento Final (Qtd)</Label>
                      <Input
                        type="number"
                        value={editRendQty}
                        onChange={(e) => setEditRendQty(e.target.value)}
                        placeholder="Ex.: 200"
                        className="bg-white/60 dark:bg-black/20 border-[#57715B]/15 focus-visible:ring-[#57715B]/30 rounded-xl"
                      />
                    </div>
                    <div className="w-28 space-y-1">
                      <Label className="text-xs">Unidade</Label>
                      <Input
                        value={editRendUnit}
                        onChange={(e) => setEditRendUnit(e.target.value)}
                        placeholder="ml / un / g"
                        className="bg-white/60 dark:bg-black/20 border-[#57715B]/15 focus-visible:ring-[#57715B]/30 rounded-xl"
                      />
                    </div>
                  </div>
                </div>
                <Button
                  className="mt-3 w-full bg-[#57715B] hover:bg-[#465b49] text-white rounded-xl"
                  onClick={handleSaveCmv}
                  disabled={isSavingCmv}
                >
                  {isSavingCmv ? (
                    <Loader2 size={14} className="animate-spin mr-2" />
                  ) : (
                    <Save size={14} className="mr-2" />
                  )}
                  Salvar Produto Final
                </Button>
              </div>

              {/* Breakdown de custo */}
              <div>
                <p className="text-[10px] uppercase tracking-widest text-muted-foreground mb-3 font-semibold">
                  Breakdown do Custo
                </p>
                <div className="space-y-2">
                  <div className="flex items-center justify-between p-3 bg-amber-50 dark:bg-amber-900/10 rounded-xl border border-amber-200/30">
                    <span className="flex items-center gap-1.5 text-xs text-amber-700 dark:text-amber-400">
                      <ChefHat size={12} /> Receita
                    </span>
                    <span className="font-bold tabular-nums text-sm text-amber-700 dark:text-amber-400">
                      {formatMoney(custoReceita)}
                    </span>
                  </div>
                  <div className="flex items-center justify-between p-3 bg-blue-50 dark:bg-blue-900/10 rounded-xl border border-blue-200/30">
                    <span className="flex items-center gap-1.5 text-xs text-blue-700 dark:text-blue-400">
                      <Package size={12} /> Embalagens
                    </span>
                    <span className="font-bold tabular-nums text-sm text-blue-700 dark:text-blue-400">
                      {formatMoney(custoEmbalagens)}
                    </span>
                  </div>
                  <div className="flex items-center justify-between p-3 bg-orange-50 dark:bg-orange-900/10 rounded-xl border border-orange-200/30">
                    <span className="flex items-center gap-1.5 text-xs text-orange-700 dark:text-orange-400">
                      <DollarSign size={12} /> Avulsos
                    </span>
                    <span className="font-bold tabular-nums text-sm text-orange-700 dark:text-orange-400">
                      {formatMoney(custoAvulsos)}
                    </span>
                  </div>
                  <div className="flex items-center justify-between p-4 bg-[#57715B]/10 rounded-xl border border-[#57715B]/20 mt-1">
                    <span className="flex items-center gap-1.5 text-sm font-bold text-[#57715B] uppercase tracking-wide">
                      <Calculator size={14} /> Total
                    </span>
                    <span className="font-black tabular-nums text-xl text-[#57715B]">
                      {formatMoney(custoTotal)}
                    </span>
                  </div>
                  {cmv.rendimento_quantidade != null && cmv.rendimento_quantidade > 0 && (
                    <div className="text-[10px] text-right text-muted-foreground pt-1">
                      = {formatMoney(custoTotal / cmv.rendimento_quantidade)} /{' '}
                      {cmv.rendimento_unidade ?? 'un'}
                    </div>
                  )}
                </div>
              </div>
            </div>
          )}

          {/* ══════════════════════════════════════════
              NODE FICHA BASE
          ══════════════════════════════════════════ */}
          {kind === 'ficha' && fichaData && (
            <div className="space-y-5">
              <div>
                <h2 className="text-xl font-bold text-[#2D362E] dark:text-[#E6DCCF] mb-1">
                  {fichaData.nome}
                </h2>
                <div className="flex items-center gap-2 flex-wrap">
                  <span className="text-amber-600 bg-amber-50 dark:bg-amber-900/20 px-2.5 py-1 rounded-full text-xs font-bold uppercase tracking-wider">
                    Rende: {fichaData.rendimento_quantidade} {fichaData.rendimento_unidade}
                  </span>
                  <span className="text-slate-600 bg-slate-100 dark:bg-slate-800 px-2.5 py-1 rounded-full text-xs font-bold uppercase tracking-wider">
                    {fichaData.status}
                  </span>
                </div>
              </div>

              {/* Custo unitário da receita */}
              <div className="bg-white/60 dark:bg-[#1A1A1A]/60 rounded-2xl p-4 border border-[#57715B]/10">
                <div className="text-xs uppercase tracking-wider text-muted-foreground font-semibold mb-1">
                  Custo Total da Ficha
                </div>
                <div className="text-3xl font-black tabular-nums text-[#2D362E] dark:text-[#E6DCCF]">
                  {formatMoney(fichaData.custo_calculado)}
                </div>
                {fichaData.rendimento_quantidade > 0 && (
                  <div className="text-emerald-600 font-bold text-lg tabular-nums mt-4 pt-4 border-t border-[#57715B]/10">
                    {formatMoney(fichaUnitCost)} / {fichaData.rendimento_unidade}
                  </div>
                )}
                {cmv?.quantidade_ficha != null && cmv.unidade_ficha && (
                  <div className="text-xs text-muted-foreground mt-2">
                    Usa {cmv.quantidade_ficha} {cmv.unidade_ficha} por produto final
                  </div>
                )}
              </div>

              {/* Editor de quantidade da receita no produto final */}
              <div className="bg-white/60 dark:bg-[#1A1A1A]/60 rounded-2xl p-4 border border-[#57715B]/10 space-y-3">
                <p className="text-[10px] uppercase tracking-widest text-muted-foreground font-semibold">
                  Quanto desta receita entra em 1 produto final?
                </p>
                <div className="flex gap-2">
                  <div className="flex-1 space-y-1">
                    <Label className="text-xs">Quantidade</Label>
                    <Input
                      type="number"
                      value={editQuantidadeFicha}
                      onChange={(e) => setEditQuantidadeFicha(e.target.value)}
                      placeholder="Ex.: 200"
                      className="bg-white/60 dark:bg-black/20 border-[#57715B]/15 focus-visible:ring-[#57715B]/30 rounded-xl"
                    />
                  </div>
                  <div className="w-28 space-y-1">
                    <Label className="text-xs">Unidade</Label>
                    <select
                      value={editUnidadeFicha}
                      onChange={(e) => setEditUnidadeFicha(e.target.value)}
                      className="w-full h-10 rounded-xl bg-white/60 dark:bg-black/20 border border-[#57715B]/15 focus:ring-2 focus:ring-[#57715B]/30 text-sm px-3 text-[#2D362E] dark:text-[#E6DCCF]"
                    >
                      {UNIDADES_FICHA.map((u) => (
                        <option key={u} value={u}>
                          {u}
                        </option>
                      ))}
                    </select>
                  </div>
                </div>

                {/* Preview em tempo real */}
                {fichaContribPreview !== null && (
                  <div className="bg-amber-50 dark:bg-amber-900/10 rounded-xl p-3 border border-amber-200/30">
                    <p className="text-[10px] uppercase tracking-wider text-amber-700 dark:text-amber-400 font-semibold mb-0.5">
                      Contribuição estimada da receita
                    </p>
                    <p className="text-lg font-black tabular-nums text-amber-700 dark:text-amber-400">
                      {formatMoney(fichaContribPreview)}
                    </p>
                  </div>
                )}

                {/* Contribuição atual vinda do banco */}
                <div className="bg-white/40 dark:bg-black/10 rounded-xl p-3 border border-[#57715B]/5">
                  <p className="text-[10px] uppercase tracking-wider text-muted-foreground font-semibold mb-0.5">
                    Receita contribui (banco)
                  </p>
                  <p className="text-lg font-black tabular-nums text-[#57715B]">
                    {formatMoney(custoReceita)}
                  </p>
                  <p className="text-[10px] text-muted-foreground mt-0.5">
                    = total do produto − embalagens − avulsos
                  </p>
                </div>

                <Button
                  className="w-full bg-[#57715B] hover:bg-[#465b49] text-white rounded-xl"
                  onClick={handleSaveFicha}
                  disabled={isSavingFicha}
                >
                  {isSavingFicha ? (
                    <Loader2 size={14} className="animate-spin mr-2" />
                  ) : (
                    <Save size={14} className="mr-2" />
                  )}
                  Salvar Quantidade da Receita
                </Button>
              </div>
            </div>
          )}

          {/* ══════════════════════════════════════════
              NODE ITEM — Embalagem
          ══════════════════════════════════════════ */}
          {kind === 'item' && selectedItem?.tipo === 'embalagem' && (
            <div className="space-y-6">
              <div>
                <h2 className="text-xl font-bold text-[#2D362E] dark:text-[#E6DCCF] mb-1">
                  {selectedItem.produtoMaster?.nome ??
                    selectedItem.insumo?.nome ??
                    selectedItem.observacao ??
                    'Embalagem'}
                </h2>
              </div>

              {selectedNFItem ? (
                <div className="bg-white/60 dark:bg-[#1A1A1A]/60 rounded-2xl p-4 border border-[#57715B]/10 space-y-3">
                  <div className="flex items-center justify-between">
                    <span className="text-[10px] uppercase tracking-wider text-[#57715B] font-bold flex items-center gap-1.5">
                      <Receipt size={12} /> NF Atrelada
                    </span>
                    <Button
                      variant="ghost"
                      size="sm"
                      className="h-6 px-2 text-[10px] text-[#57715B] hover:bg-[#57715B]/10"
                      onClick={handleDesatrelarNF}
                      disabled={isSaving}
                    >
                      Usar valor fixo
                    </Button>
                  </div>
                  <div>
                    <div className="font-semibold text-sm">{selectedNFItem.fornecedor}</div>
                    <div className="text-xs text-muted-foreground flex items-center gap-2 mt-1">
                      <span>NF: {selectedNFItem.numero_nota}</span>
                      <span>•</span>
                      <span className="flex items-center gap-1">
                        <Calendar size={10} /> {formatDate(selectedNFItem.data_nota)}
                      </span>
                    </div>
                  </div>
                  <div className="flex items-end justify-between pt-2 border-t border-[#57715B]/10">
                    <div className="text-lg font-bold tabular-nums text-[#2D362E] dark:text-[#E6DCCF]">
                      {formatMoney(selectedNFItem.valor_unitario)}
                    </div>
                    <Button
                      variant="outline"
                      size="sm"
                      className="h-7 text-xs border-[#57715B]/20 hover:bg-[#57715B]/5"
                      onClick={() => setAtrelarNFOpen(true)}
                    >
                      Trocar NF
                    </Button>
                  </div>
                </div>
              ) : (
                <div className="bg-white/60 dark:bg-[#1A1A1A]/60 rounded-2xl p-4 border border-[#57715B]/10 space-y-3">
                  <div className="flex items-center justify-between mb-2">
                    <span className="text-[10px] uppercase tracking-wider text-muted-foreground font-bold">
                      Valor Fixo
                    </span>
                    <Button
                      variant="outline"
                      size="sm"
                      className="h-7 text-xs border-[#57715B]/20 hover:bg-[#57715B]/5 text-[#57715B]"
                      onClick={() => setAtrelarNFOpen(true)}
                    >
                      <Receipt size={12} className="mr-1.5" /> Atrelar NF
                    </Button>
                  </div>
                  <div className="space-y-1">
                    <Label className="text-xs">Preço Unitário (R$)</Label>
                    <Input
                      type="number"
                      value={editPreco}
                      onChange={(e) => setEditPreco(e.target.value)}
                      className="bg-white/60 dark:bg-black/20 border-[#57715B]/15 focus-visible:ring-[#57715B]/30 rounded-xl"
                    />
                  </div>
                </div>
              )}

              <div className="space-y-4">
                <div className="space-y-1">
                  <Label className="text-xs">Unidades por pacote/caixa</Label>
                  <Input
                    type="number"
                    value={editUnidadesPorEmbalagem}
                    onChange={(e) => setEditUnidadesPorEmbalagem(e.target.value)}
                    className="bg-white/60 dark:bg-black/20 border-[#57715B]/15 focus-visible:ring-[#57715B]/30 rounded-xl"
                    placeholder="Ex: 100"
                  />
                  <p className="text-[10px] text-muted-foreground">
                    Quantas unidades vêm na embalagem comprada.
                  </p>
                </div>

                <div className="grid grid-cols-2 gap-3">
                  <div className="space-y-1">
                    <Label className="text-xs">Uso na Ficha (Qtd)</Label>
                    <Input
                      type="number"
                      value={editQty}
                      onChange={(e) => setEditQty(e.target.value)}
                      className="bg-white/60 dark:bg-black/20 border-[#57715B]/15 focus-visible:ring-[#57715B]/30 rounded-xl"
                    />
                  </div>
                  <div className="space-y-1">
                    <Label className="text-xs">Unidade de Uso</Label>
                    <Input
                      value={editUnit}
                      onChange={(e) => setEditUnit(e.target.value)}
                      className="bg-white/60 dark:bg-black/20 border-[#57715B]/15 focus-visible:ring-[#57715B]/30 rounded-xl"
                    />
                  </div>
                </div>
              </div>

              <div className="flex items-center justify-between p-4 bg-emerald-50 dark:bg-emerald-900/10 rounded-2xl border border-emerald-500/20">
                <span className="text-xs font-bold uppercase tracking-wider text-emerald-700 dark:text-emerald-400">
                  Custo Calculado
                </span>
                <span className="text-xl font-black tabular-nums text-emerald-700 dark:text-emerald-400">
                  {formatMoney(selectedItem.custo_calculado)}
                </span>
              </div>
            </div>
          )}

          {/* ══════════════════════════════════════════
              NODE ITEM — Custo avulso
          ══════════════════════════════════════════ */}
          {kind === 'item' && selectedItem?.tipo === 'outro' && (
            <div className="space-y-6">
              <div className="space-y-1">
                <Label className="text-xs">Nome / Observação</Label>
                <Input
                  value={editObs}
                  onChange={(e) => setEditObs(e.target.value)}
                  className="bg-white/60 dark:bg-black/20 border-[#57715B]/15 focus-visible:ring-[#57715B]/30 rounded-xl"
                />
              </div>

              <div className="bg-white/60 dark:bg-[#1A1A1A]/60 rounded-2xl p-4 border border-[#57715B]/10 space-y-3">
                <div className="space-y-1">
                  <Label className="text-xs">Valor Fixo (R$)</Label>
                  <Input
                    type="number"
                    value={editPreco}
                    onChange={(e) => setEditPreco(e.target.value)}
                    className="bg-white/60 dark:bg-black/20 border-[#57715B]/15 focus-visible:ring-[#57715B]/30 rounded-xl"
                  />
                </div>
              </div>

              <div className="grid grid-cols-2 gap-3">
                <div className="space-y-1">
                  <Label className="text-xs">Quantidade</Label>
                  <Input
                    type="number"
                    value={editQty}
                    onChange={(e) => setEditQty(e.target.value)}
                    className="bg-white/60 dark:bg-black/20 border-[#57715B]/15 focus-visible:ring-[#57715B]/30 rounded-xl"
                  />
                </div>
                <div className="space-y-1">
                  <Label className="text-xs">Unidade</Label>
                  <Input
                    value={editUnit}
                    onChange={(e) => setEditUnit(e.target.value)}
                    className="bg-white/60 dark:bg-black/20 border-[#57715B]/15 focus-visible:ring-[#57715B]/30 rounded-xl"
                  />
                </div>
              </div>

              <div className="flex items-center justify-between p-4 bg-emerald-50 dark:bg-emerald-900/10 rounded-2xl border border-emerald-500/20">
                <span className="text-xs font-bold uppercase tracking-wider text-emerald-700 dark:text-emerald-400">
                  Custo Calculado
                </span>
                <span className="text-xl font-black tabular-nums text-emerald-700 dark:text-emerald-400">
                  {formatMoney(selectedItem.custo_calculado)}
                </span>
              </div>
            </div>
          )}

          {/* ══════════════════════════════════════════
              NODE NF — Nota Fiscal
          ══════════════════════════════════════════ */}
          {isNotaNode && selectedNotaNodesData && (
            <div className="space-y-4">
              <h2 className="text-xl font-bold text-[#2D362E] dark:text-[#E6DCCF]">
                Nota Fiscal: {selectedNotaNodesData.numero_nota}
              </h2>
              <div className="bg-white/60 dark:bg-[#1A1A1A]/60 rounded-2xl p-4 border border-[#57715B]/10 space-y-3">
                <div className="flex justify-between items-start">
                  <span className="text-xs uppercase tracking-wider text-muted-foreground font-bold">
                    Fornecedor
                  </span>
                  <span className="text-sm font-semibold text-right">
                    {selectedNotaNodesData.fornecedor}
                  </span>
                </div>
                <div className="flex justify-between items-start">
                  <span className="text-xs uppercase tracking-wider text-muted-foreground font-bold">
                    Data da Nota
                  </span>
                  <span className="text-sm font-medium">
                    {formatDate(selectedNotaNodesData.data_nota)}
                  </span>
                </div>
              </div>
            </div>
          )}
        </div>

        {/* ── FOOTER — botões de ação para items ── */}
        {kind === 'item' && selectedItem && (
          <div className="p-4 border-t border-[#57715B]/10 bg-white/95 dark:bg-[#1A1A1A]/95 shrink-0 flex items-center gap-2">
            <Button
              variant="outline"
              className="flex-1 border-red-200 text-red-600 hover:bg-red-50 hover:text-red-700 dark:border-red-900/30 dark:hover:bg-red-900/20 rounded-xl"
              onClick={() => setDeleteDialogOpen(true)}
              disabled={isDeleting || isSaving}
            >
              {isDeleting ? (
                <Loader2 size={16} className="animate-spin mr-2" />
              ) : (
                <Trash2 size={16} className="mr-2" />
              )}
              Excluir
            </Button>
            <Button
              className="flex-[2] bg-[#57715B] hover:bg-[#465b49] text-white rounded-xl"
              onClick={handleSaveItem}
              disabled={isSaving || isDeleting}
            >
              {isSaving ? (
                <Loader2 size={16} className="animate-spin mr-2" />
              ) : (
                <Save size={16} className="mr-2" />
              )}
              Salvar Alterações
            </Button>
          </div>
        )}
      </aside>

      {/* ── Confirmação de exclusão ── */}
      <AlertDialog open={deleteDialogOpen} onOpenChange={setDeleteDialogOpen}>
        <AlertDialogContent className="bg-white/90 dark:bg-[#1A1A1A]/90 backdrop-blur-xl border-white/40 dark:border-white/10 rounded-2xl">
          <AlertDialogHeader>
            <AlertDialogTitle className="text-[#2D362E] dark:text-[#E6DCCF]">
              Excluir item?
            </AlertDialogTitle>
            <AlertDialogDescription>
              Esta ação não pode ser desfeita. O item será removido permanentemente do CMV.
            </AlertDialogDescription>
          </AlertDialogHeader>
          <AlertDialogFooter>
            <AlertDialogCancel className="bg-white/60 dark:bg-black/20 border-[#57715B]/15 hover:bg-[#57715B]/5 rounded-xl">
              Cancelar
            </AlertDialogCancel>
            <AlertDialogAction
              onClick={handleDeleteItem}
              className="bg-red-600 hover:bg-red-700 text-white rounded-xl"
            >
              {isDeleting ? <Loader2 size={14} className="animate-spin mr-1" /> : null}
              Excluir
            </AlertDialogAction>
          </AlertDialogFooter>
        </AlertDialogContent>
      </AlertDialog>

      {/* ── Atrelar NF dialog ── */}
      {selectedItem && (
        <CmvAtrelarNFDialog
          open={atrelarNFOpen}
          cmvItemId={selectedItem.id}
          embalagemNome={
            selectedItem.produtoMaster?.nome ??
            selectedItem.insumo?.nome ??
            selectedItem.observacao ??
            'Embalagem'
          }
          currentNfItemId={selectedItem.nf_item_id}
          onClose={() => setAtrelarNFOpen(false)}
          onSaved={onRefetch}
        />
      )}
    </>
  );
}
